// [IndexMax]+1 bars, and [BadParam] for a parameter out of range or histories
// of different lengths.
func (c *Core) AROONOpen(inHigh, inLow []float64, optInTimePeriod int) (*AROONStream, float64, float64, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, 0, 0, BadParam
	}
	sp, err := c.aroonOpenInternal(inHigh, inLow, 0, int32(optInTimePeriod))
	if err != nil {
		return nil, 0, 0, err
	}
	return sp, sp.cur_outAroonDown, sp.cur_outAroonUp, nil
}

// AROONOpenAndFill opens a stream as [Core.AROONOpen] does and also writes the
// outputs over the whole history, as [Core.AROON] writes them for bars 0
// through len(inHigh)-1, returning that range.
//
// Each output must hold len(inHigh) minus [Core.AROONLookback] values and share
// no memory with an input or another output.
//
// The errors are those of [Core.AROONOpen], and [BadParam] for an output that
// is empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) AROONOpenAndFill(inHigh, inLow []float64, optInTimePeriod int, outAroonDown, outAroonUp []float64) (*AROONStream, OutRange, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.aroonLookback(int32(optInTimePeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inHigh) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inHigh)-lookback, 0)
	if len(outAroonDown) == 0 || len(outAroonDown) < outLen {
		return nil, OutRange{}, BadParam
	}
	if len(outAroonUp) == 0 || len(outAroonUp) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outAroonDown, inHigh) || sameStart(outAroonDown, inLow) || sameStart(outAroonUp, inHigh) || sameStart(outAroonUp, inLow) || sameStart(outAroonDown, outAroonUp) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && (overlaps(outAroonDown, inHigh) || overlaps(outAroonDown, inLow) || overlaps(outAroonUp, inHigh) || overlaps(outAroonUp, inLow) || overlaps(outAroonDown, outAroonUp)) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.aroonOpenAndFillInternal(inHigh, inLow, 0, int32(optInTimePeriod), &outBegIdx, &outNBElement, outAroonDown, outAroonUp)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
